/**
 * `just up`. Sequences the modules; holds no logic of its own beyond argument parsing, so the
 * testable parts stay in their own files.
 */

import { createInterface } from 'node:readline/promises';
import { spawnResolved } from './command.mjs';
import { existsSync, rmSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { resolveIdentifier } from './instance.mjs';
import { resolveDevServerPorts } from './ports.mjs';
import { renderAll, renderNginxConf } from './render.mjs';
import { formatReport, run, runChecks } from './preflight.mjs';
import { attachInstance, detachInstance, ensureProxy, hostGatewayIpv4 } from './proxy.mjs';
import {
  anyExited,
  awaitDevServersReady,
  finishDevServers,
  INTERRUPTED,
  notAnswering,
  selectDevServers,
  startDevServers,
  stoppedMessage,
  superviseStartup,
} from './devservers.mjs';
import { postgresHint, urlTable } from './report.mjs';
import {
  compose,
  composeCaptured,
  envFileFor,
  logFileFor,
  postgresHostPort,
  readProxyPort,
  realmHashMarkerFor,
  runCaptured,
  seededMarkerFor,
  stateDirFor,
  unhealthyServices,
} from './compose.mjs';
import { runStep, StepFailedError } from './steps.mjs';
import {
  compareRealmHash,
  hashRealm,
  readStoredRealmHash,
  realmDriftMessage,
  writeRealmHash,
} from './realm-drift.mjs';
import { runEntryPoint } from './entrypoint.mjs';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

/**
 * `seed` stays null unless `--seed` or `--no-seed` answers the question up front; null leaves it to
 * `resolveSeedDecision`.
 */
export function parseArgs(argv) {
  const options = { fresh: false, detach: false, apps: null, seed: null, limesurvey: false };
  for (const arg of argv) {
    if (arg === '--fresh') {
      options.fresh = true;
    } else if (arg === '--detach') {
      options.detach = true;
    } else if (arg === '--seed' || arg === '--no-seed') {
      options.seed = seedFlag(arg, options.seed);
    } else if (arg === '--with-limesurvey') {
      options.limesurvey = true;
    } else if (arg.startsWith('--apps=')) {
      options.apps = arg.slice('--apps='.length);
    } else {
      throw new Error(
        `Unknown option "${arg}". Valid: --fresh, --detach, --seed, --no-seed, --apps=<names>, ` +
          '--with-limesurvey.',
      );
    }
  }
  return options;
}

function seedFlag(arg, earlierSeed) {
  const seed = arg === '--seed';
  if (earlierSeed === null || earlierSeed === seed) {
    return seed;
  } else {
    throw new Error(
      'Conflicting options "--seed" and "--no-seed". Pass one of them, or neither to be asked.',
    );
  }
}

const SEED_ANSWERS = new Map([
  ['', true],
  ['y', true],
  ['yes', true],
  ['n', false],
  ['no', false],
]);

/** Enter means yes. Anything that is neither yes nor no is null, so the caller asks again. */
export function parseSeedAnswer(answer) {
  return SEED_ANSWERS.get(answer.trim().toLowerCase()) ?? null;
}

/**
 * Whether this run seeds, or `INTERRUPTED`. Only an instance that was seeded before asks: an empty
 * database has one sensible answer, and a run that is not interactive (CI, a script, output
 * redirected to a file) must never wait on a question nobody sees.
 */
export async function resolveSeedDecision({ seed, databaseIsFresh, interactive, prompt }) {
  if (seed === null) {
    if (databaseIsFresh || !interactive) {
      return true;
    } else {
      return await askToReseed(prompt);
    }
  } else {
    return seed;
  }
}

async function askToReseed(prompt) {
  try {
    let decision = null;
    while (decision === null) {
      decision = parseSeedAnswer(await prompt('Re-seed the sample data?', 'Y/n'));
    }
    return decision;
  } catch (error) {
    // Ctrl-C or Ctrl-D at the question closes the prompt with an AbortError. That is an interrupt
    // like any other, not a failure.
    if (error.name === 'AbortError') {
      return INTERRUPTED;
    } else {
      throw error;
    }
  }
}

/**
 * Which database steps a run takes. The realm bookkeeping follows `databaseIsFresh` — Keycloak
 * imports the rendered realm exactly when its database is fresh — and only seeding follows the seed
 * decision, so a re-seed never records a realm hash or skips the drift check.
 */
export function databaseSteps({ databaseIsFresh, willSeed }) {
  return {
    checkRealmDrift: !databaseIsFresh,
    recordRealmHash: databaseIsFresh,
    seeding: seedingFor({ databaseIsFresh, willSeed }),
  };
}
